#!/data/data/com.termux/files/usr/bin/bash
set -e

echo "=========================================================="
echo "🚀 IMS PRO STUDIO v5000.0 — GLOBAL OTA FOR ALL v500/v650 DEVICES"
echo "=========================================================="

if [ ! -f "pubspec.yaml" ] && [ -d "$HOME/dj-player" ]; then
  cd "$HOME/dj-player"
fi
mkdir -p lib .github/workflows assets

echo "🧹 1/5 Cleaning legacy files..."
rm -f all_codes_v100.txt all_codes_v200.txt part1_karaoke_and_daily_fix.txt part2_native_dsp_and_push.txt
rm -f fix_karaoke_3_issues.sh fix_kotlin_build.sh fix_loud_volume.sh fix_pure_sound_and_10s_funk.sh
rm -f fix_share_to_cricket_and_extractor.sh fix_zero_delay_and_direct_funk_list.sh
rm -f update_commentary_only.sh update_janimurthy_voice_v306.sh update_reels_spectrum_v308.sh upgrade_real_tile_studio_v307.sh

echo "🎨 2/5 Installing Professional IMS App Icon (assets/icon.png)..."
