cat << 'EOF_WORKFLOW_YML' > .github/workflows/main.yml
name: Build IMS Pro Studio APK

on:
  push:
    branches: [ "main", "master" ]
    tags: [ "v*" ]
  workflow_dispatch:

permissions:
  contents: write

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout Repository
        uses: actions/checkout@v4

      - name: Set up Java 17
        uses: actions/setup-java@v4
        with:
          distribution: 'temurin'
          java-version: '17'

      - name: Set up Flutter Stable
        uses: subosito/flutter-action@v2
        with:
          channel: 'stable'

      - name: Generate Fresh Android V2 Scaffold First
        run: |
          rm -rf android
          flutter create --platforms=android --org com.gajanan.djplaycommentry --project-name dj_player .
          grep -n "void main()" lib/main.dart

      - name: Inject Glassmorphic MediaSession Lockscreen Service, Zero-Popup WakeLock, Hardware DSP & TTS
        run: |
          MAIN_KT=$(find android/app/src/main -name "MainActivity.kt" | head -n 1)
          PKG_DIR=$(dirname "$MAIN_KT")
          PKG_LINE=$(head -n 1 "$MAIN_KT")

          cat << 'SVCEOF' > "$PKG_DIR/DjMediaForegroundService.kt"
          $PKG_LINE
          import android.app.Notification
          import android.app.NotificationChannel
          import android.app.NotificationManager
          import android.app.PendingIntent
          import android.app.Service
          import android.content.Context
          import android.content.Intent
          import android.content.pm.ServiceInfo
          import android.graphics.Bitmap
          import android.graphics.BitmapFactory
          import android.graphics.Canvas
          import android.graphics.Color
          import android.graphics.LinearGradient
          import android.graphics.Paint
          import android.graphics.RectF
          import android.graphics.Shader
          import android.graphics.Typeface
          import android.media.MediaMetadata
          import android.media.session.MediaSession
          import android.media.session.PlaybackState
          import android.net.wifi.WifiManager
          import android.os.Build
          import android.os.Handler
          import android.os.IBinder
          import android.os.Looper
          import android.os.PowerManager
          import java.net.HttpURLConnection
          import java.net.URL

          class DjMediaForegroundService : Service() {
              private var wakeLock: PowerManager.WakeLock? = null
              private var wifiLock: WifiManager.WifiLock? = null
              private var mediaSession: MediaSession? = null

              private var currentSeqId: Int = 0
              private var currentTitle: String = "IMS Pro Studio"
              private var currentArtist: String = "320kbps Master Engine • Auto-Next Active"
              private var currentCoverUrl: String = ""
              private var currentIsPlaying: Boolean = true
              private var currentPosMs: Long = 0L
              private var currentDurMs: Long = 210000L
              private var cachedArtUrl: String = ""
              private var cachedArtBitmap: Bitmap? = null

              override fun onCreate() {
                  super.onCreate()
                  acquireLocks()
                  initMediaSession()
              }

              private fun acquireLocks() {
                  try {
                      val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
                      if (wakeLock == null) {
                          wakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "IMS::MediaWakeLock")
                          wakeLock?.setReferenceCounted(false)
                      }
                      if (wakeLock?.isHeld == false) {
                          wakeLock?.acquire(12 * 60 * 60 * 1000L)
                      }
                  } catch (_: Exception) {}

                  try {
                      val wm = applicationContext.getSystemService(Context.WIFI_SERVICE) as WifiManager
                      if (wifiLock == null) {
                          wifiLock = wm.createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF, "IMS::MediaWifiLock")
                          wifiLock?.setReferenceCounted(false)
                      }
                      if (wifiLock?.isHeld == false) {
                          wifiLock?.acquire()
                      }
                  } catch (_: Exception) {}
              }

              private fun initMediaSession() {
                  try {
                      val session = MediaSession(this, "IMSProMediaSession")
                      session.setCallback(object : MediaSession.Callback() {
                          override fun onPlay() {
                              currentIsPlaying = true
                              MainActivity.dispatchMediaCommandToFlutter("PLAY")
                              refreshNotificationAndSession()
                          }

                          override fun onPause() {
                              currentIsPlaying = false
                              MainActivity.dispatchMediaCommandToFlutter("PAUSE")
                              refreshNotificationAndSession()
                          }

                          override fun onSkipToNext() {
                              cachedArtBitmap = null
                              currentPosMs = 0L
                              MainActivity.dispatchMediaCommandToFlutter("NEXT")
                          }

                          override fun onSkipToPrevious() {
                              cachedArtBitmap = null
                              currentPosMs = 0L
                              MainActivity.dispatchMediaCommandToFlutter("PREV")
                          }

                          override fun onSeekTo(pos: Long) {
                              currentPosMs = pos
                              MainActivity.dispatchMediaCommandToFlutter("SEEK:$pos")
                              refreshNotificationAndSession()
                          }
                      })
                      session.isActive = true
                      mediaSession = session
                  } catch (_: Exception) {}
              }

              override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
                  acquireLocks()
                  if (mediaSession == null) {
                      initMediaSession()
                  }

                  val action = intent?.action ?: ""
                  if (action == "ACTION_PREV") {
                      cachedArtBitmap = null
                      currentPosMs = 0L
                      MainActivity.dispatchMediaCommandToFlutter("PREV")
                      return START_STICKY
                  } else if (action == "ACTION_TOGGLE") {
                      currentIsPlaying = !currentIsPlaying
                      MainActivity.dispatchMediaCommandToFlutter("TOGGLE")
                      refreshNotificationAndSession()
                      return START_STICKY
                  } else if (action == "ACTION_NEXT") {
                      cachedArtBitmap = null
                      currentPosMs = 0L
                      MainActivity.dispatchMediaCommandToFlutter("NEXT")
                      return START_STICKY
                  } else if (action == "ACTION_AIRHORN") {
                      MainActivity.dispatchMediaCommandToFlutter("AIRHORN")
                      return START_STICKY
                  }

                  if (intent?.hasExtra("title") == true) {
                      val incomingSeq = intent.getIntExtra("seqId", 0)
                      if (incomingSeq > 0 && incomingSeq < currentSeqId) {
                          return START_STICKY
                      }
                      if (incomingSeq > 0) {
                          currentSeqId = incomingSeq
                      }
                      val newTitle = intent.getStringExtra("title") ?: currentTitle
                      val titleChanged = (newTitle != currentTitle)
                      currentTitle = newTitle
                      currentArtist = intent.getStringExtra("artist") ?: currentArtist
                      val newCover = intent.getStringExtra("cover") ?: ""
                      currentIsPlaying = intent.getBooleanExtra("isPlaying", true)
                      currentPosMs = intent.getLongExtra("positionMs", 0L)
                      currentDurMs = intent.getLongExtra("durationMs", 210000L).coerceAtLeast(1000L)

                      if (newCover != currentCoverUrl || titleChanged) {
                          currentCoverUrl = newCover
                          cachedArtUrl = ""
                          cachedArtBitmap = null
                          if (newCover.isNotEmpty()) {
                              fetchAndStylizeCoverArtAsync(newCover, currentTitle, currentSeqId)
                          }
                      }
                  }

                  refreshNotificationAndSession()
                  return START_STICKY
              }

              private fun fetchAndStylizeCoverArtAsync(urlStr: String, expectedTitle: String, expectedSeq: Int) {
                  Thread {
                      try {
                          val conn = URL(urlStr).openConnection() as HttpURLConnection
                          conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Android 14)")
                          conn.connectTimeout = 5000
                          conn.readTimeout = 5000
                          conn.instanceFollowRedirects = true
                          val rawBmp = conn.inputStream.use { BitmapFactory.decodeStream(it) }
                          if (rawBmp != null && urlStr == currentCoverUrl && expectedSeq == currentSeqId) {
                              val stylized = renderGlassmorphicAlbumArt(rawBmp, expectedTitle)
                              Handler(Looper.getMainLooper()).post {
                                  if (urlStr == currentCoverUrl && expectedSeq == currentSeqId) {
                                      cachedArtUrl = urlStr
                                      cachedArtBitmap = stylized
                                      refreshNotificationAndSession()
                                  }
                              }
                          }
                      } catch (_: Exception) {}
                  }.start()
              }

              private fun renderGlassmorphicAlbumArt(source: Bitmap?, title: String): Bitmap {
                  val size = 512
                  val out = Bitmap.createBitmap(size, size, Bitmap.Config.ARGB_8888)
                  val canvas = Canvas(out)
                  val paint = Paint(Paint.ANTI_ALIAS_FLAG)

                  if (source != null) {
                      val scaled = Bitmap.createScaledBitmap(source, size, size, true)
                      canvas.drawBitmap(scaled, 0f, 0f, paint)
                  } else {
                      paint.shader = LinearGradient(
                          0f, 0f, size.toFloat(), size.toFloat(),
                          intArrayOf(Color.parseColor("#071024"), Color.parseColor("#132854"), Color.parseColor("#09152E")),
                          null, Shader.TileMode.CLAMP
                      )
                      canvas.drawRect(0f, 0f, size.toFloat(), size.toFloat(), paint)
                      paint.shader = null

                      paint.style = Paint.Style.STROKE
                      paint.strokeWidth = 6f
                      paint.color = Color.parseColor("#00E5FF")
                      canvas.drawCircle(size / 2f, size / 2f - 20f, 130f, paint)

                      paint.style = Paint.Style.FILL
                      paint.color = Color.parseColor("#FFD740")
                      paint.textSize = 86f
                      paint.typeface = Typeface.create(Typeface.DEFAULT, Typeface.BOLD)
                      paint.textAlign = Paint.Align.CENTER
                      canvas.drawText("IMS", size / 2f, size / 2f + 10f, paint)
                  }

                  // Draw Frosted Glassmorphic Top & Bottom Overlay Strip + Neon Cyan/Gold Frame
                  val glassPaint = Paint(Paint.ANTI_ALIAS_FLAG)
                  glassPaint.shader = LinearGradient(
                      0f, size - 110f, 0f, size.toFloat(),
                      intArrayOf(Color.argb(175, 8, 16, 36), Color.argb(235, 5, 10, 24)),
                      null, Shader.TileMode.CLAMP
                  )
                  canvas.drawRoundRect(RectF(16f, size - 96f, size - 16f, size - 16f), 22f, 22f, glassPaint)

                  val borderPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                      style = Paint.Style.STROKE
                      strokeWidth = 3.5f
                      color = Color.parseColor("#00E5FF")
                  }
                  canvas.drawRoundRect(RectF(16f, size - 96f, size - 16f, size - 16f), 22f, 22f, borderPaint)

                  val outerFrame = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                      style = Paint.Style.STROKE
                      strokeWidth = 8f
                      color = Color.parseColor("#FFD740")
                  }
                  canvas.drawRoundRect(RectF(4f, 4f, size - 4f, size - 4f), 28f, 28f, outerFrame)

                  val textPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply {
                      color = Color.parseColor("#FFD740")
                      textSize = 26f
                      typeface = Typeface.create(Typeface.DEFAULT, Typeface.BOLD)
                      textAlign = Paint.Align.CENTER
                  }
                  canvas.drawText("✨ IMS PRO STUDIO • 320K MASTER", size / 2f, size - 46f, textPaint)

                  return out
              }

              private fun refreshNotificationAndSession() {
                  val artBmp = cachedArtBitmap ?: renderGlassmorphicAlbumArt(null, currentTitle)
                  try {
                      val metaBuilder = MediaMetadata.Builder()
                          .putString(MediaMetadata.METADATA_KEY_TITLE, currentTitle)
                          .putString(MediaMetadata.METADATA_KEY_DISPLAY_TITLE, currentTitle)
                          .putString(MediaMetadata.METADATA_KEY_ARTIST, currentArtist)
                          .putString(MediaMetadata.METADATA_KEY_DISPLAY_SUBTITLE, currentArtist)
                          .putString(MediaMetadata.METADATA_KEY_ALBUM, currentArtist)
                          .putLong(MediaMetadata.METADATA_KEY_DURATION, currentDurMs)
                          .putBitmap(MediaMetadata.METADATA_KEY_ALBUM_ART, artBmp)
                          .putBitmap(MediaMetadata.METADATA_KEY_ART, artBmp)
                          .putBitmap(MediaMetadata.METADATA_KEY_DISPLAY_ICON, artBmp)
                      mediaSession?.setMetadata(metaBuilder.build())

                      val stateInt = if (currentIsPlaying) PlaybackState.STATE_PLAYING else PlaybackState.STATE_PAUSED
                      val actions = PlaybackState.ACTION_PLAY or
                          PlaybackState.ACTION_PAUSE or
                          PlaybackState.ACTION_PLAY_PAUSE or
                          PlaybackState.ACTION_SKIP_TO_NEXT or
                          PlaybackState.ACTION_SKIP_TO_PREVIOUS or
                          PlaybackState.ACTION_SEEK_TO

                      val pbState = PlaybackState.Builder()
                          .setActions(actions)
                          .setState(stateInt, currentPosMs, if (currentIsPlaying) 1.0f else 0.0f)
                          .build()
                      mediaSession?.setPlaybackState(pbState)
                  } catch (_: Exception) {}

                  val notif = buildMediaNotification(currentTitle, currentArtist, currentIsPlaying, artBmp)
                  try {
                      if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                          startForeground(1001, notif, ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK)
                      } else {
                          startForeground(1001, notif)
                      }
                      val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
                      nm.notify(1001, notif)
                  } catch (_: Exception) {}
              }

              private fun serviceActionPendingIntent(reqCode: Int, actionStr: String): PendingIntent {
                  val svcIntent = Intent(this, DjMediaForegroundService::class.java).apply {
                      action = actionStr
                  }
                  val flags = PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                  return if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                      PendingIntent.getForegroundService(this, reqCode, svcIntent, flags)
                  } else {
                      PendingIntent.getService(this, reqCode, svcIntent, flags)
                  }
              }

              private fun buildMediaNotification(
                  title: String,
                  artist: String,
                  isPlaying: Boolean,
                  artBmp: Bitmap
              ): Notification {
                  val channelId = "ims_pro_glass_media_v650"
                  val nm = getSystemService(Context.NOTIFICATION_SERVICE) as NotificationManager
                  if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                      val ch = NotificationChannel(
                          channelId,
                          "IMS Pro Lockscreen & Media Controls",
                          NotificationManager.IMPORTANCE_LOW
                      ).apply {
                          description = "Luxury Glassmorphic Lockscreen & Notification Media Player"
                          setShowBadge(true)
                          lockscreenVisibility = Notification.VISIBILITY_PUBLIC
                      }
                      nm.createNotificationChannel(ch)
                  }

                  val openIntent = Intent(this, MainActivity::class.java).apply {
                      flags = Intent.FLAG_ACTIVITY_SINGLE_TOP
                  }
                  val contentPi = PendingIntent.getActivity(
                      this, 10, openIntent,
                      PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
                  )

                  val prevPi = serviceActionPendingIntent(21, "ACTION_PREV")
                  val togglePi = serviceActionPendingIntent(22, "ACTION_TOGGLE")
                  val nextPi = serviceActionPendingIntent(23, "ACTION_NEXT")
                  val hornPi = serviceActionPendingIntent(24, "ACTION_AIRHORN")

                  val builder = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                      Notification.Builder(this, channelId)
                  } else {
                      Notification.Builder(this)
                  }

                  val mediaStyle = Notification.MediaStyle()
                      .setShowActionsInCompactView(0, 1, 2)
                  if (mediaSession != null) {
                      mediaStyle.setMediaSession(mediaSession!!.sessionToken)
                  }

                  builder.setSmallIcon(android.R.drawable.ic_media_play)
                      .setLargeIcon(artBmp)
                      .setContentTitle(title)
                      .setContentText(artist)
                      .setSubText("IMS Pro Studio • 320kbps")
                      .setContentIntent(contentPi)
                      .setVisibility(Notification.VISIBILITY_PUBLIC)
                      .setColor(Color.parseColor("#0A1630"))
                      .setColorized(true)
                      .setOngoing(isPlaying)
                      .setStyle(mediaStyle)
                      .addAction(android.R.drawable.ic_media_previous, "Previous", prevPi)
                      .addAction(
                          if (isPlaying) android.R.drawable.ic_media_pause else android.R.drawable.ic_media_play,
                          if (isPlaying) "Pause" else "Play",
                          togglePi
                      )
                      .addAction(android.R.drawable.ic_media_next, "Next", nextPi)
                      .addAction(android.R.drawable.ic_lock_silent_mode_off, "DJ Horn", hornPi)

                  return builder.build()
              }

              override fun onDestroy() {
                  try {
                      mediaSession?.release()
                  } catch (_: Exception) {}
                  try {
                      if (wakeLock?.isHeld == true) wakeLock?.release()
                  } catch (_: Exception) {}
                  try {
                      if (wifiLock?.isHeld == true) wifiLock?.release()
                  } catch (_: Exception) {}
                  super.onDestroy()
              }

              override fun onBind(intent: Intent?): IBinder? = null
          }
          SVCEOF
          sed -i "s|\$PKG_LINE|$PKG_LINE|g" "$PKG_DIR/DjMediaForegroundService.kt"

          cat << 'KTEOF' > "$MAIN_KT"
          $PKG_LINE
          import android.Manifest
