          import java.net.HttpURLConnection
          import java.net.URL
          import java.nio.ByteBuffer
          import java.util.Locale

          class MainActivity: FlutterActivity(), TextToSpeech.OnInitListener {
              companion object {
                  var sharedMethodChannel: MethodChannel? = null

                  fun dispatchMediaCommandToFlutter(cmd: String) {
                      Handler(Looper.getMainLooper()).post {
                          sharedMethodChannel?.invokeMethod("onMediaNotificationAction", cmd)
                      }
                  }
              }

              private var tts: TextToSpeech? = null
              private var ttsReady: Boolean = false
              private var recorder: MediaRecorder? = null
              private var currentRecordPath: String? = null
              private var methodChannel: MethodChannel? = null
              private var pendingFileResult: MethodChannel.Result? = null
              private var pendingIsVideo: Boolean = false
              private var initialSharedMedia: String? = null

              private var masterEq: Equalizer? = null
              private var masterBass: BassBoost? = null
              private var masterLoudness: LoudnessEnhancer? = null
              private var masterVirtualizer: Virtualizer? = null
              private var directWakeLock: PowerManager.WakeLock? = null
              private var directWifiLock: WifiManager.WifiLock? = null

              private val bgHeartbeatHandler = Handler(Looper.getMainLooper())
              private val bgHeartbeatRunnable = object : Runnable {
                  override fun run() {
                      methodChannel?.invokeMethod("onMediaNotificationAction", "HEARTBEAT")
                      bgHeartbeatHandler.postDelayed(this, 2500)
                  }
              }

              override fun onCreate(savedInstanceState: Bundle?) {
                  super.onCreate(savedInstanceState)
                  tts = TextToSpeech(this, this)
                  handleIncomingShareIntent(intent)

                  try {
                      val pm = getSystemService(Context.POWER_SERVICE) as PowerManager
                      directWakeLock = pm.newWakeLock(PowerManager.PARTIAL_WAKE_LOCK, "IMS::DirectCpuLock").apply {
                          setReferenceCounted(false)
                          acquire(12 * 60 * 60 * 1000L)
                      }
                  } catch (_: Exception) {}

                  try {
                      val wm = applicationContext.getSystemService(Context.WIFI_SERVICE) as WifiManager
                      directWifiLock = wm.createWifiLock(WifiManager.WIFI_MODE_FULL_HIGH_PERF, "IMS::DirectWifiLock").apply {
                          setReferenceCounted(false)
                          acquire()
                      }
                  } catch (_: Exception) {}

                  bgHeartbeatHandler.postDelayed(bgHeartbeatRunnable, 2500)
              }

              override fun onNewIntent(intent: Intent) {
                  super.onNewIntent(intent)
                  handleIncomingShareIntent(intent)
              }

              private fun handleIncomingShareIntent(intent: Intent?) {
                  if (intent == null) return
                  if (Intent.ACTION_SEND == intent.action) {
                      val sharedText = intent.getStringExtra(Intent.EXTRA_TEXT)
                      val sharedStream = intent.getParcelableExtra<Uri>(Intent.EXTRA_STREAM)
                      if (!sharedText.isNullOrEmpty()) {
                          initialSharedMedia = sharedText
                          Handler(Looper.getMainLooper()).postDelayed({
                              methodChannel?.invokeMethod("onSharedMedia", sharedText)
                          }, 500)
                      } else if (sharedStream != null) {
                          val extracted = copyUriAndExtractAudio(sharedStream, true)
                          if (extracted != null) {
                              initialSharedMedia = extracted
                              methodChannel?.invokeMethod("onSharedMedia", extracted)
                          }
                      }
                  }
              }

              override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
                  super.onActivityResult(requestCode, resultCode, data)
                  if (requestCode == 701) {
                      if (resultCode == Activity.RESULT_OK && data?.data != null) {
                          val path = copyUriAndExtractAudio(data.data!!, pendingIsVideo)
                          pendingFileResult?.success(path)
                      } else {
                          pendingFileResult?.success(null)
                      }
                      pendingFileResult = null
                  }
              }

              private fun copyUriAndExtractAudio(uri: Uri, extractIfVideo: Boolean): String? {
                  return try {
                      val mime = contentResolver.getType(uri) ?: ""
                      val isVid = extractIfVideo || mime.startsWith("video")
                      val ext = if (isVid) ".mp4" else ".m4a"
                      val tempIn = File(filesDir, "picked_${System.currentTimeMillis()}$ext")
                      contentResolver.openInputStream(uri)?.use { input ->
                          FileOutputStream(tempIn).use { output ->
                              input.copyTo(output)
                          }
                      }
                      if (isVid) {
                          extractAudioTrackHardware(tempIn.absolutePath) ?: tempIn.absolutePath
                      } else {
                          tempIn.absolutePath
                      }
                  } catch (_: Exception) {
                      null
                  }
              }

              private fun extractAudioTrackHardware(videoPath: String): String? {
                  return try {
                      val outAudioFile = File(filesDir, "extracted_audio_${System.currentTimeMillis()}.m4a")
                      val extractor = MediaExtractor()
                      extractor.setDataSource(videoPath)
                      var audioTrackIndex = -1
                      for (i in 0 until extractor.trackCount) {
                          val format = extractor.getTrackFormat(i)
                          val mime = format.getString(MediaFormat.KEY_MIME) ?: ""
                          if (mime.startsWith("audio/")) {
                              audioTrackIndex = i
                              break
                          }
                      }
                      if (audioTrackIndex < 0) {
                          extractor.release()
                          return videoPath
                      }
                      extractor.selectTrack(audioTrackIndex)
                      val format = extractor.getTrackFormat(audioTrackIndex)
                      val muxer = MediaMuxer(outAudioFile.absolutePath, MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4)
                      val dstIndex = muxer.addTrack(format)
                      muxer.start()
                      val buffer = ByteBuffer.allocate(256 * 1024)
                      val bufferInfo = MediaCodec.BufferInfo()
                      while (true) {
                          val sampleSize = extractor.readSampleData(buffer, 0)
                          if (sampleSize < 0) break
                          bufferInfo.offset = 0
                          bufferInfo.size = sampleSize
                          bufferInfo.presentationTimeUs = extractor.sampleTime
                          bufferInfo.flags = extractor.sampleFlags
                          muxer.writeSampleData(dstIndex, buffer, bufferInfo)
                          extractor.advance()
                      }
                      muxer.stop()
                      muxer.release()
                      extractor.release()
                      outAudioFile.absolutePath
                  } catch (_: Exception) {
                      videoPath
                  }
              }

              private fun resolveAndExtractUrlNative(rawShareText: String, result: MethodChannel.Result) {
                  val urlRegex = Regex("https?://[^\\s\"<>]+")
                  val match = urlRegex.find(rawShareText)
                  val targetUrl = match?.value ?: rawShareText.trim()
                  var completed = false
                  val mainHandler = Handler(Looper.getMainLooper())

                  fun finishWithUrl(mediaUrl: String?) {
                      if (completed) return
                      completed = true
                      if (mediaUrl == null) {
                          mainHandler.post { result.success(null) }
                          return
                      }
                      Thread {
                          try {
                              val conn = URL(mediaUrl).openConnection() as HttpURLConnection
                              conn.setRequestProperty("User-Agent", "Mozilla/5.0 (Linux; Android 14) AppleWebKit/537.36 Chrome/124.0 Mobile Safari/537.36")
                              conn.connectTimeout = 12000
                              conn.readTimeout = 20000
                              conn.instanceFollowRedirects = true
                              val tempVid = File(filesDir, "native_reel_${System.currentTimeMillis()}.mp4")
                              conn.inputStream.use { inp ->
                                  FileOutputStream(tempVid).use { out ->
                                      inp.copyTo(out)
                                  }
                              }
                              if (tempVid.exists() && tempVid.length() > 10000) {
                                  val audioPath = extractAudioTrackHardware(tempVid.absolutePath) ?: tempVid.absolutePath
                                  mainHandler.post { result.success(audioPath) }
                              } else {
                                  mainHandler.post { result.success(null) }
                              }
                          } catch (_: Exception) {
                              mainHandler.post { result.success(null) }
                          }
                      }.start()
                  }

                  mainHandler.post {
                      try {
                          val wv = WebView(applicationContext)
                          wv.settings.javaScriptEnabled = true
                          wv.settings.domStorageEnabled = true
                          wv.settings.mediaPlaybackRequiresUserGesture = false
                          wv.settings.userAgentString = "Mozilla/5.0 (Linux; Android 14; Pixel 8) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Mobile Safari/537.36"

                          wv.webViewClient = object : WebViewClient() {
                              override fun shouldInterceptRequest(view: WebView?, request: WebResourceRequest?): WebResourceResponse? {
                                  val reqUrl = request?.url?.toString() ?: ""
                                  if (!completed && (reqUrl.contains(".mp4") || reqUrl.contains(".m4a") || reqUrl.contains("googlevideo.com/videoplayback") || reqUrl.contains("cdninstagram.com") || reqUrl.contains("fbcdn.net")) && !reqUrl.contains(".jpg") && !reqUrl.contains(".png") && !reqUrl.contains(".webp")) {
                                      if (reqUrl.contains("mp4") || reqUrl.contains("videoplayback") || reqUrl.contains("audio")) {
                                          mainHandler.post {
                                              try { wv.destroy() } catch (_: Exception) {}
                                          }
                                          finishWithUrl(reqUrl)
                                      }
                                  }
                                  return super.shouldInterceptRequest(view, request)
                              }

                              override fun onPageFinished(view: WebView?, url: String?) {
                                  super.onPageFinished(view, url)
                                  view?.evaluateJavascript(
                                      "(function(){ var v = document.querySelector('video'); if(v && v.src) return v.src; var m = document.querySelector('meta[property=\"og:video\"]'); if(m) return m.content; return ''; })()"
                                  ) { resStr ->
                                      val clean = resStr?.replace("\"", "")?.trim() ?: ""
                                      if (!completed && clean.startsWith("http")) {
                                          try { wv.destroy() } catch (_: Exception) {}
                                          finishWithUrl(clean)
                                      }
                                  }
                              }
                          }

                          val loadUrl = if (targetUrl.contains("instagram.com")) {
                              val sc = Regex("(?:reel|reels|p)/([A-Za-z0-9_-]+)").find(targetUrl)?.groupValues?.get(1)
                              if (sc != null) "https://www.instagram.com/p/$sc/embed/captioned/" else targetUrl
                          } else {
                              targetUrl
                          }
                          wv.loadUrl(loadUrl)

                          mainHandler.postDelayed({
                              if (!completed) {
                                  try { wv.destroy() } catch (_: Exception) {}
                                  finishWithUrl(null)
                              }
                          }, 9500)
                      } catch (_: Exception) {
                          finishWithUrl(null)
                      }
                  }
              }

              override fun onInit(status: Int) {
                  ttsReady = (status == TextToSpeech.SUCCESS)
              }

              override fun onKeyDown(keyCode: Int, event: KeyEvent?): Boolean {
                  if (keyCode == KeyEvent.KEYCODE_VOLUME_UP) {
                      methodChannel?.invokeMethod("onVolumeKey", "UP")
                  } else if (keyCode == KeyEvent.KEYCODE_VOLUME_DOWN) {
                      methodChannel?.invokeMethod("onVolumeKey", "DOWN")
                  } else if (keyCode == KeyEvent.KEYCODE_MEDIA_NEXT) {
                      methodChannel?.invokeMethod("onMediaNotificationAction", "NEXT")
                  } else if (keyCode == KeyEvent.KEYCODE_MEDIA_PREVIOUS) {
                      methodChannel?.invokeMethod("onMediaNotificationAction", "PREV")
                  } else if (keyCode == KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE) {
                      methodChannel?.invokeMethod("onMediaNotificationAction", "TOGGLE")
                  }
                  return super.onKeyDown(keyCode, event)
              }

              private fun selectBestNaturalVoice(locale: Locale) {
                  try {
                      val voices = tts?.voices ?: return
                      var bestVoice: Voice? = null
                      var bestScore = -1000
                      for (v in voices) {
                          if (v.locale.language == locale.language) {
                              val n = v.name.lowercase()
                              var score = v.quality
                              if (n.contains("knm") || n.contains("knd") || n.contains("him") || n.contains("hid") ||
                                  n.contains("enm") || n.contains("end") || n.contains("gbm") || n.contains("aub") ||
                                  n.contains("male") || n.contains("-b") || n.contains("-d")) {
                                  score += 600
                              }
                              if (n.contains("knf") || n.contains("hif") || n.contains("enf") || n.contains("female") || n.contains("-a") || n.contains("-c")) {
                                  score -= 500
                              }
                              if (n.contains("network") || n.contains("wavenet")) {
                                  score += 300
                              }
                              if (score > bestScore) {
                                  bestScore = score
                                  bestVoice = v
                              }
                          }
                      }
                      if (bestVoice != null) {
                          tts?.voice = bestVoice
                      } else {
                          tts?.language = locale
                      }
                  } catch (_: Exception) {
                      tts?.language = locale
                  }
              }

              private fun applyHardwareDsp(bassStrength: Int, loudnessMb: Int, bands: List<Int>) {
                  try {
                      if (masterEq == null) {
                          masterEq = Equalizer(0, 0).apply { enabled = true }
                      }
                      val eq = masterEq
                      if (eq != null) {
                          val numBands = eq.numberOfBands.toInt()
                          for (i in 0 until minOf(numBands, bands.size)) {
                              eq.setBandLevel(i.toShort(), bands[i].toShort())
                          }
                      }
                  } catch (_: Exception) {}

                  try {
                      if (masterBass == null) {
                          masterBass = BassBoost(0, 0).apply { enabled = true }
                      }
                      masterBass?.setStrength(bassStrength.coerceIn(0, 1000).toShort())
                  } catch (_: Exception) {}

                  try {
                      if (masterLoudness == null) {
                          masterLoudness = LoudnessEnhancer(0).apply { enabled = true }
                      }
                      masterLoudness?.setTargetGain(loudnessMb.coerceIn(0, 1500))
                  } catch (_: Exception) {}
              }

              private fun installOtaApkFile(rawPath: String) {
                  try {
                      val srcFile = File(rawPath)
                      if (!srcFile.exists()) return
                      val pubDir = externalCacheDir ?: cacheDir
                      val pubApk = File(pubDir, "ims_pro_ota_1000.apk")
                      srcFile.copyTo(pubApk, overwrite = true)
                      pubApk.setReadable(true, false)

                      StrictMode.setVmPolicy(StrictMode.VmPolicy.Builder().build())
                      val apkUri = Uri.fromFile(pubApk)
                      val installIntent = Intent(Intent.ACTION_VIEW).apply {
                          setDataAndType(apkUri, "application/vnd.android.package-archive")
                          addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
                          addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
                      }
                      // Directly target Android's built-in system PackageInstaller so ES File Explorer & Termux never show "Open with"!
                      val resolved = packageManager.queryIntentActivities(installIntent, 0)
                      for (info in resolved) {
                          val pkg = info.activityInfo.packageName.lowercase()
                          if (pkg.contains("packageinstaller") || pkg == "android") {
                              installIntent.setClassName(info.activityInfo.packageName, info.activityInfo.name)
                              break
                          }
                      }
                      startActivity(installIntent)
                  } catch (_: Exception) {}
              }

              private fun startIsolatedVoiceRecorder(fileName: String, useEchoCancelledSource: Boolean): String? {
                  if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
                      if (checkSelfPermission(Manifest.permission.RECORD_AUDIO) != PackageManager.PERMISSION_GRANTED) {
                          requestPermissions(arrayOf(Manifest.permission.RECORD_AUDIO), 201)
                          return null
                      }
                  }
                  try {
                      recorder?.release()
                      val outFile = File(filesDir, fileName + ".m4a")
                      currentRecordPath = outFile.absolutePath
                      recorder = MediaRecorder().apply {
                          if (useEchoCancelledSource) {
                              setAudioSource(MediaRecorder.AudioSource.VOICE_COMMUNICATION)
                          } else {
                              setAudioSource(MediaRecorder.AudioSource.MIC)
                          }
                          setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)
                          setAudioEncoder(MediaRecorder.AudioEncoder.AAC)
                          setAudioEncodingBitRate(192000)
                          setAudioSamplingRate(44100)
                          setOutputFile(currentRecordPath)
                          prepare()
                          start()
                      }
                      return currentRecordPath
                  } catch (_: Exception) {
                      return try {
                          recorder?.release()
                          val outFile = File(filesDir, fileName + ".m4a")
                          currentRecordPath = outFile.absolutePath
                          recorder = MediaRecorder().apply {
                              setAudioSource(MediaRecorder.AudioSource.MIC)
                              setOutputFormat(MediaRecorder.OutputFormat.MPEG_4)
                              setAudioEncoder(MediaRecorder.AudioEncoder.AAC)
                              setAudioEncodingBitRate(192000)
                              setAudioSamplingRate(44100)
                              setOutputFile(currentRecordPath)
                              prepare()
                              start()
                          }
                          currentRecordPath
                      } catch (_: Exception) {
                          null
                      }
                  }
              }

              override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
                  super.configureFlutterEngine(flutterEngine)
                  val ch = MethodChannel(flutterEngine.dartExecutor.binaryMessenger, "dj_native_tts")
                  methodChannel = ch
                  sharedMethodChannel = ch
                  ch.setMethodCallHandler { call, result ->
                      when (call.method) {
                          "updateMediaNotification" -> {
                              val seqId = (call.argument<Number>("seqId")?.toInt()) ?: 0
                              val title = call.argument<String>("title") ?: "IMS Pro Studio"
                              val artist = call.argument<String>("artist") ?: "Playing in Background"
                              val cover = call.argument<String>("cover") ?: ""
                              val isPlaying = call.argument<Boolean>("isPlaying") ?: true
                              val posMs = (call.argument<Number>("positionMs")?.toLong()) ?: 0L
                              val durMs = (call.argument<Number>("durationMs")?.toLong()) ?: 210000L
                              try {
                                  val svcIntent = Intent(this, DjMediaForegroundService::class.java).apply {
                                      putExtra("seqId", seqId)
                                      putExtra("title", title)
                                      putExtra("artist", artist)
                                      putExtra("cover", cover)
                                      putExtra("isPlaying", isPlaying)
                                      putExtra("positionMs", posMs)
                                      putExtra("durationMs", durMs)
                                  }
                                  if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                                      startForegroundService(svcIntent)
                                  } else {
                                      startService(svcIntent)
                                  }
                              } catch (_: Exception) {}
                              result.success(true)
                          }
                          "resetAudioToNormalFlat" -> {
                              try {
                                  masterEq?.enabled = false
                                  masterEq?.release()
                                  masterEq = null
                              } catch (_: Exception) {}
                              try {
                                  masterBass?.enabled = false
                                  masterBass?.release()
                                  masterBass = null
                              } catch (_: Exception) {}
                              try {
                                  masterLoudness?.enabled = false
                                  masterLoudness?.release()
                                  masterLoudness = null
                              } catch (_: Exception) {}
                              try {
                                  masterVirtualizer?.enabled = false
                                  masterVirtualizer?.release()
                                  masterVirtualizer = null
                              } catch (_: Exception) {}
                              try {
                                  val am = getSystemService(Context.AUDIO_SERVICE) as AudioManager
                                  if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.M) {
                                      am.adjustStreamVolume(AudioManager.STREAM_MUSIC, AudioManager.ADJUST_UNMUTE, 0)
                                  }
                                  val curVol = am.getStreamVolume(AudioManager.STREAM_MUSIC)
                                  val maxVol = am.getStreamMaxVolume(AudioManager.STREAM_MUSIC)
                                  if (curVol <= 0 && maxVol > 0) {
                                      am.setStreamVolume(AudioManager.STREAM_MUSIC, (maxVol * 0.65).toInt().coerceAtLeast(1), 0)
                                  }
                              } catch (_: Exception) {}
                              result.success(true)
                          }
                          "setHardwareDsp" -> {
                              val bass = call.argument<Int>("bass") ?: 0
                              val loudness = call.argument<Int>("loudness") ?: 0
                              val bands = call.argument<List<Int>>("bands") ?: listOf(0, 0, 0, 0, 0)
                              applyHardwareDsp(bass, loudness, bands)
                              result.success(true)
                          }
                          "installApkOta" -> {
                              val path = call.argument<String>("path") ?: ""
                              installOtaApkFile(path)
                              result.success(true)
                          }
                          "speak" -> {
                              if (!ttsReady || tts == null) {
                                  result.success(false)
                                  return@setMethodCallHandler
                              }
                              val text = call.argument<String>("text") ?: ""
                              val lang = call.argument<String>("lang") ?: "kn-IN"
                              val basePitch = (call.argument<Double>("pitch") ?: 0.92).toFloat()
                              val baseRate = (call.argument<Double>("rate") ?: 1.20).toFloat()
                              val locale = Locale.forLanguageTag(lang)
                              val avail = tts?.isLanguageAvailable(locale) ?: TextToSpeech.LANG_NOT_SUPPORTED
                              if (avail < TextToSpeech.LANG_AVAILABLE) {
                                  result.success(false)
                                  return@setMethodCallHandler
                              }
                              tts?.stop()
                              selectBestNaturalVoice(locale)

                              val parts = text.split(" | ")
                              if (parts.size >= 3) {
                                  tts?.setPitch((basePitch * 1.10f).coerceIn(0.75f, 1.35f))
                                  tts?.setSpeechRate((baseRate * 1.06f).coerceIn(0.95f, 1.45f))
                                  tts?.speak(parts[0], TextToSpeech.QUEUE_FLUSH, null, "utt_w1")

                                  tts?.setPitch((basePitch * 0.94f).coerceIn(0.72f, 1.25f))
                                  tts?.setSpeechRate((baseRate * 1.03f).coerceIn(0.95f, 1.40f))
                                  tts?.speak(parts[1], TextToSpeech.QUEUE_ADD, null, "utt_w2")

                                  tts?.setPitch((basePitch * 1.03f).coerceIn(0.75f, 1.30f))
                                  tts?.setSpeechRate((baseRate * 0.98f).coerceIn(0.90f, 1.35f))
                                  val speakRes = tts?.speak(parts.subList(2, parts.size).joinToString(" "), TextToSpeech.QUEUE_ADD, null, "utt_w3")
                                  result.success(speakRes == TextToSpeech.SUCCESS)
                              } else {
                                  tts?.setPitch(basePitch)
                                  tts?.setSpeechRate(baseRate)
                                  val speakRes = tts?.speak(text, TextToSpeech.QUEUE_FLUSH, null, "dj_single_utt")
                                  result.success(speakRes == TextToSpeech.SUCCESS)
                              }
                          }
                          "stopSpeak" -> {
                              tts?.stop()
                              result.success(true)
                          }
                          "setKaraokeVocalCut" -> {
                              val enabled = call.argument<Boolean>("enabled") ?: true
                              val strength = (call.argument<Double>("strength") ?: 1.0).toFloat().coerceIn(0.0f, 1.0f)
                              try {
                                  if (masterEq == null) {
                                      masterEq = Equalizer(0, 0).apply { this.enabled = true }
                                  }
                                  val eq = masterEq
                                  if (eq != null) {
                                      val numBands = eq.numberOfBands.toInt()
                                      if (enabled && strength > 0.05f) {
                                          val targetLevels = listOf(
                                              750,
                                              (-1200 * strength).toInt(),
                                              (-1500 * strength).toInt(),
                                              (-1350 * strength).toInt(),
                                              700
                                          )
                                          for (i in 0 until minOf(numBands, targetLevels.size)) {
                                              eq.setBandLevel(i.toShort(), targetLevels[i].toShort())
                                          }
                                      } else {
                                          eq.enabled = false
                                      }
                                  }
                              } catch (_: Exception) {}
                              try {
                                  if (enabled && strength > 0.05f) {
                                      if (masterVirtualizer == null) {
                                          masterVirtualizer = Virtualizer(0, 0).apply { this.enabled = true }
                                      } else {
                                          masterVirtualizer?.enabled = true
                                      }
                                      masterVirtualizer?.setStrength((1000 * strength).toInt().coerceIn(0, 1000).toShort())
                                  } else {
                                      masterVirtualizer?.enabled = false
                                  }
                              } catch (_: Exception) {}
                              result.success(true)
                          }
                          "startCleanVocalRecord" -> {
                              val name = call.argument<String>("name") ?: "karaoke_vocal"
                              val path = startIsolatedVoiceRecorder(name, true)
                              result.success(path)
                          }
                          "stopCleanVocalRecord" -> {
                              try {
                                  recorder?.stop()
                              } catch (_: Exception) {}
                              recorder?.release()
                              recorder = null
                              try {
                                  val src = currentRecordPath?.let { File(it) }
                                  if (src != null && src.exists() && src.length() > 500) {
                                      val dlDir = Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_DOWNLOADS)
                                      dlDir.mkdirs()
                                      val publicFile = File(dlDir, "IMS_Karaoke_" + src.name)
                                      src.copyTo(publicFile, overwrite = true)
                                      MediaScannerConnection.scanFile(this, arrayOf(publicFile.absolutePath), arrayOf("audio/mp4"), null)
                                  }
                              } catch (_: Exception) {}
                              result.success(currentRecordPath)
                          }
                          "startRecord" -> {
                              val name = call.argument<String>("name") ?: "voice_clip"
                              val path = startIsolatedVoiceRecorder(name, false)
                              result.success(path)
                          }
                          "stopRecord" -> {
                              try {
                                  recorder?.stop()
                                  recorder?.release()
                                  recorder = null
                                  result.success(currentRecordPath)
                              } catch (_: Exception) {
                                  recorder?.release()
                                  recorder = null
                                  result.success(currentRecordPath)
                              }
                          }
                          "pickMediaAndExtractAudio" -> {
                              pendingFileResult = result
                              pendingIsVideo = call.argument<Boolean>("isVideo") ?: false
                              val intent = Intent(Intent.ACTION_GET_CONTENT).apply {
                                  type = if (pendingIsVideo) "video/*" else "audio/*"
                                  addCategory(Intent.CATEGORY_OPENABLE)
                              }
                              startActivityForResult(Intent.createChooser(intent, "Select Media"), 701)
                          }
                          "extractAudioFromUri" -> {
                              val u = call.argument<String>("uri") ?: ""
                              if (u.startsWith("content://")) {
                                  result.success(copyUriAndExtractAudio(Uri.parse(u), true))
                              } else {
                                  result.success(extractAudioTrackHardware(u))
                              }
                          }
                          "getInitialSharedMedia" -> {
                              val s = initialSharedMedia
                              initialSharedMedia = null
                              result.success(s)
                          }
                          "resolveAndExtractUrlNative" -> {
                              val u = call.argument<String>("url") ?: ""
                              resolveAndExtractUrlNative(u, result)
                          }
                          else -> result.notImplemented()
                      }
                  }
              }

              override fun onDestroy() {
                  bgHeartbeatHandler.removeCallbacks(bgHeartbeatRunnable)
                  try {
                      if (directWakeLock?.isHeld == true) directWakeLock?.release()
                  } catch (_: Exception) {}
                  try {
                      if (directWifiLock?.isHeld == true) directWifiLock?.release()
                  } catch (_: Exception) {}
                  tts?.stop()
                  tts?.shutdown()
                  recorder?.release()
                  masterEq?.release()
                  masterBass?.release()
                  masterLoudness?.release()
                  masterVirtualizer?.release()
                  super.onDestroy()
              }
          }
          KTEOF
          sed -i "s|\$PKG_LINE|$PKG_LINE|g" "$MAIN_KT"

      - name: Configure AndroidManifest Permissions, IMS App Label, Foreground Media Service & Custom IMS Icon
        run: |
          MANIFEST="android/app/src/main/AndroidManifest.xml"
          if [ -f "$MANIFEST" ]; then
            sed -i 's/android:label="[^"]*"/android:label="IMS"/g' "$MANIFEST"
            if ! grep -q "usesCleartextTraffic" "$MANIFEST"; then
              sed -i 's/<application/<application android:usesCleartextTraffic="true"/' "$MANIFEST"
            fi
            if ! grep -q "android.permission.INTERNET" "$MANIFEST"; then
              sed -i 's/<application/<uses-permission android:name="android.permission.INTERNET"\/>\n    <uses-permission android:name="android.permission.WAKE_LOCK"\/>\n    <uses-permission android:name="android.permission.ACCESS_WIFI_STATE"\/>\n    <uses-permission android:name="android.permission.CHANGE_WIFI_STATE"\/>\n    <uses-permission android:name="android.permission.FOREGROUND_SERVICE"\/>\n    <uses-permission android:name="android.permission.FOREGROUND_SERVICE_MEDIA_PLAYBACK"\/>\n    <uses-permission android:name="android.permission.REQUEST_INSTALL_PACKAGES"\/>\n    <uses-permission android:name="android.permission.POST_NOTIFICATIONS"\/>\n    <uses-permission android:name="android.permission.RECORD_AUDIO"\/>\n    <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE"\/>\n    <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE"\/>\n    <uses-permission android:name="android.permission.READ_MEDIA_AUDIO"\/>\n    <uses-permission android:name="android.permission.MODIFY_AUDIO_SETTINGS"\/>\n    <application/' "$MANIFEST"
            fi
            if ! grep -q "DjMediaForegroundService" "$MANIFEST"; then
              sed -i 's|</application>|    <service android:name=".DjMediaForegroundService" android:enabled="true" android:exported="false" android:foregroundServiceType="mediaPlayback" />\n    </application>|g' "$MANIFEST"
            fi
            if ! grep -q "android.intent.action.SEND" "$MANIFEST"; then
              sed -i 's|<category android:name="android.intent.category.LAUNCHER"/>|<category android:name="android.intent.category.LAUNCHER"/></intent-filter><intent-filter><action android:name="android.intent.action.SEND"/><category android:name="android.intent.category.DEFAULT"/><data android:mimeType="text/plain"/><data android:mimeType="video/*"/><data android:mimeType="audio/*"/>|g' "$MANIFEST"
            fi
          fi
          if [ -f "assets/icon.png" ]; then
            for dir in android/app/src/main/res/mipmap-*; do
              if [ -d "$dir" ]; then
                cp -f assets/icon.png "$dir/ic_launcher.png" || true
                cp -f assets/icon.png "$dir/ic_launcher_round.png" || true
              fi
            done
            rm -rf android/app/src/main/res/mipmap-anydpi-v26
          fi

      - name: Build IMS Pro Studio v5000.0 Flagship Release APK
        run: |
          flutter pub get
          flutter build apk --release --no-tree-shake-icons

      - name: Publish APK to GitHub Releases (v5000)
        uses: softprops/action-gh-release@v2
        with:
          tag_name: v5000
          name: "IMS Pro Studio v5000.0 Flagship OTA Release"
          make_latest: true
          files: build/app/outputs/flutter-apk/app-release.apk
        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}
EOF_WORKFLOW_YML
echo "  ✅ Wrote .github/workflows/main.yml"

cat << 'EOF_OTA_DART' > lib/ota_update_engine.dart
import 'dart:async';
import 'dart:convert';
import 'dart:io';
import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:http/http.dart' as http;
import 'package:path_provider/path_provider.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'entry_music_data.dart';

/// Loop-Free Smart OTA Engine (v5000.0):
/// 1) Uses a fixed deterministic build number (5000) in both APK and ota_version.json so once installed, 5000 == 5000 (NEVER loops!).
/// 2) Records `ims_ota_attempted_build_v5000` BEFORE launching the system package installer so it never re-triggers in a loop.
/// 3) Directly targets Android's native `packageinstaller` (bypasses Termux & ES File Explorer "Open with" sheet).
class OtaUpdateEngine {
  static const int currentBuildNumber = 5000;
  static const String currentVersionName = '5000.0';
  static const String githubRepoOwner = 'GajananPatagar';
  static const String githubRepoName = 'dj-player';

  static const MethodChannel _nativeChannel = MethodChannel('dj_native_tts');

  static final ValueNotifier<String> otaStatusBanner = ValueNotifier<String>(
    '✨ IMS v5000.0 Pro • Exact-Match Audio & Anti-Mute Lock Active',
  );
  static final ValueNotifier<double?> otaDownloadProgress = ValueNotifier<double?>(null);
  static final ValueNotifier<String> dailyRefreshStamp = ValueNotifier<String>('');

  /// Controlled live from `ims_live_ota.json` on GitHub (Never displayed in UI!)
  static final ValueNotifier<String> remoteOtaPin = ValueNotifier<String>('1681');
  static final ValueNotifier<int> remoteRelockToken = ValueNotifier<int>(1);
  static final ValueNotifier<List<String>> remoteTrendingQueries = ValueNotifier<List<String>>([]);

  static Timer? _periodicTimer;
  static bool _isCheckingOrDownloading = false;

  static Future<void> initAutoOtaAndDailySelfUpdate({
    required Future<void> Function() onDailyContentRefresh,
  }) async {
    await syncInAppLiveCloudOta(onContentRefresh: onDailyContentRefresh, forceRefresh: false);
    await _checkAndRunDailySelfUpdate(onDailyContentRefresh);

    Future.delayed(const Duration(seconds: 3), () {
      checkAndAutoInstallOtaUpdate(forceManualCheck: false);
    });

    _periodicTimer?.cancel();
    _periodicTimer = Timer.periodic(const Duration(hours: 1), (_) async {
      await syncInAppLiveCloudOta(onContentRefresh: onDailyContentRefresh, forceRefresh: false);
      await _checkAndRunDailySelfUpdate(onDailyContentRefresh);
      await checkAndAutoInstallOtaUpdate(forceManualCheck: false);
    });
  }

  static String _todayDateKey() {
    final now = DateTime.now();
    return '${now.year}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
  }

  static Future<bool> syncInAppLiveCloudOta({
    Future<void> Function()? onContentRefresh,
    bool forceRefresh = false,
  }) async {
    try {
      final Map<String, String> headers = {
        'User-Agent': 'IMS-InApp-OTA/5000.0 (Android)',
        'Accept': 'application/json',
        'Cache-Control': 'no-cache',
      };

      final String liveUrl =
          'https://raw.githubusercontent.com/$githubRepoOwner/$githubRepoName/main/ims_live_ota.json?t=${DateTime.now().millisecondsSinceEpoch}';
      final res = await http.get(Uri.parse(liveUrl), headers: headers).timeout(const Duration(seconds: 5));
      if (res.statusCode == 200) {
        final Map<String, dynamic> data = jsonDecode(res.body);

        final String? banner = data['liveAnnouncement']?.toString();
        if (banner != null && banner.trim().isNotEmpty) {
          otaStatusBanner.value = banner.trim();
        }

        final String? pin = (data['activationPin'] ?? data['defaultActivationPin'])?.toString();
        if (pin != null && pin.trim().isNotEmpty) {
          remoteOtaPin.value = pin.trim();
          final prefs = await SharedPreferences.getInstance();
          await prefs.setString('ims_cached_ota_pin_v650', pin.trim());
        }

        final int? relockTok = int.tryParse((data['forceRelockToken'] ?? '1').toString());
        if (relockTok != null) {
          remoteRelockToken.value = relockTok;
        }

        if (data['extraOfflineCategories'] is List) {
          for (final rawCat in (data['extraOfflineCategories'] as List)) {
            final String c = rawCat.toString().trim();
            if (c.isNotEmpty) {
              await VaultManager.addCustomCategory(c);
            }
          }
        }

        if (data['dailyTrendingBoostQueries'] is List) {
          remoteTrendingQueries.value =
              (data['dailyTrendingBoostQueries'] as List).map((e) => e.toString()).toList();
        }

        final prefs = await SharedPreferences.getInstance();
        final String newHash = res.body.hashCode.toString();
        final String oldHash = prefs.getString('ims_live_ota_hash') ?? '';
        if (forceRefresh || (oldHash.isNotEmpty && oldHash != newHash)) {
          await prefs.setString('ims_live_ota_hash', newHash);
          if (onContentRefresh != null) {
            await onContentRefresh();
          }
          otaStatusBanner.value = '✅ IMS Cloud Synced Live (${data['versionLabel'] ?? 'IMS v5000 Pro'})';
        } else if (oldHash.isEmpty) {
          await prefs.setString('ims_live_ota_hash', newHash);
        }
        return true;
      }
    } catch (_) {}
    return false;
  }

  static Future<void> _checkAndRunDailySelfUpdate(
    Future<void> Function() onDailyContentRefresh,
  ) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final String today = _todayDateKey();
      final String lastUpdatedDay = prefs.getString('v5000_last_daily_self_update') ?? '';
      dailyRefreshStamp.value = 'Synced $today';

      if (lastUpdatedDay != today) {
        await onDailyContentRefresh();
        await prefs.setString('v5000_last_daily_self_update', today);
        otaStatusBanner.value = '🟢 Auto-Updated for $today • IMS v$currentVersionName Pro';
      }
    } catch (_) {}
  }

  /// Checks ONLY `ota_version.json` with a strict one-shot guard per buildNumber so it NEVER loops!
  static Future<bool> checkAndAutoInstallOtaUpdate({
    bool forceManualCheck = false,
    void Function(String statusText, double? progress)? onProgressCallback,
  }) async {
    if (_isCheckingOrDownloading) return false;
    _isCheckingOrDownloading = true;

    try {
      onProgressCallback?.call('🔍 Checking IMS Cloud OTA...', null);
      await syncInAppLiveCloudOta(forceRefresh: forceManualCheck);

      final prefs = await SharedPreferences.getInstance();
      final int alreadyAttemptedBuild = prefs.getInt('ims_ota_attempted_build_v5000') ?? currentBuildNumber;

      int remoteBuild = currentBuildNumber;
      String remoteVersion = currentVersionName;
      String? apkDownloadUrl;

      final Map<String, String> headers = {
        'User-Agent': 'IMS-OTA-Updater/5000.0 (Android)',
        'Accept': 'application/json',
        'Cache-Control': 'no-cache',
      };

      try {
        final String rawVersionUrl =
            'https://raw.githubusercontent.com/$githubRepoOwner/$githubRepoName/main/ota_version.json?t=${DateTime.now().millisecondsSinceEpoch}';
        final res = await http.get(Uri.parse(rawVersionUrl), headers: headers).timeout(const Duration(seconds: 6));
        if (res.statusCode == 200) {
          final Map<String, dynamic> data = jsonDecode(res.body);
          remoteBuild = int.tryParse((data['buildNumber'] ?? currentBuildNumber).toString()) ?? currentBuildNumber;
          remoteVersion = (data['versionName'] ?? currentVersionName).toString();
          apkDownloadUrl = data['apkUrl']?.toString();
        }
      } catch (_) {}

      final bool shouldTriggerApk = remoteBuild > currentBuildNumber &&
          apkDownloadUrl != null &&
          apkDownloadUrl.startsWith('http') &&
          (forceManualCheck || remoteBuild > alreadyAttemptedBuild);

      if (shouldTriggerApk) {
        // Lock this build number immediately BEFORE downloading so it can NEVER loop even if dismissed!
        await prefs.setInt('ims_ota_attempted_build_v5000', remoteBuild);
        otaStatusBanner.value = '⚡ Downloading IMS v$remoteVersion Update...';
        onProgressCallback?.call('⚡ Downloading IMS v$remoteVersion Update...', 0.05);
        await _downloadAndInstallApkOnce(
          apkDownloadUrl,
          remoteBuild,
          remoteVersion,
          onProgressCallback: onProgressCallback,
        );
        return true;
      } else {
        onProgressCallback?.call('✅ IMS v$currentVersionName is Up-To-Date', 1.0);
        if (forceManualCheck) {
          otaStatusBanner.value = '✅ Up-To-Date (IMS v$currentVersionName Build $currentBuildNumber)';
        }
      }
    } catch (_) {
    } finally {
      _isCheckingOrDownloading = false;
    }
    return false;
  }

  static Future<void> _downloadAndInstallApkOnce(
    String apkUrl,
    int targetBuild,
    String targetVersion, {
    void Function(String statusText, double? progress)? onProgressCallback,
  }) async {
    try {
      otaDownloadProgress.value = 0.02;
      final client = http.Client();
      final req = http.Request('GET', Uri.parse(apkUrl));
      req.headers['User-Agent'] = 'Mozilla/5.0 (Linux; Android 14) IMS-OTA/5000.0';
      final http.StreamedResponse response = await client.send(req).timeout(const Duration(seconds: 30));

      if (response.statusCode != 200) {
        otaDownloadProgress.value = null;
        client.close();
        return;
      }

      final int totalBytes = response.contentLength ?? 22000000;
      int receivedBytes = 0;

      final Directory dir = await getTemporaryDirectory();
      final File apkFile = File('${dir.path}/ims_ota_update_$targetBuild.apk');
      if (await apkFile.exists()) {
        await apkFile.delete();
      }
      final IOSink sink = apkFile.openWrite();

      await for (final List<int> chunk in response.stream) {
        sink.add(chunk);
        receivedBytes += chunk.length;
        final double pct = (receivedBytes / totalBytes).clamp(0.05, 0.99);
        otaDownloadProgress.value = pct;
        final String msg = '⚡ Updating IMS v$targetVersion... ${(pct * 100).toInt()}%';
        otaStatusBanner.value = msg;
        onProgressCallback?.call(msg, pct);
      }

      await sink.flush();
      await sink.close();
      client.close();

      if (await apkFile.exists() && await apkFile.length() > 3000000) {
        otaDownloadProgress.value = null;
        otaStatusBanner.value = '✅ IMS v$targetVersion Ready';
        await _nativeChannel.invokeMethod('installApkOta', {'path': apkFile.path});
      }
    } catch (_) {
    } finally {
      otaDownloadProgress.value = null;
    }
  }
}
