  Future<void> _promptCustomStartCueDialog(Map<String, dynamic> trk) async {
    final String id = (trk['id'] ?? '').toString();
    final int existing = int.tryParse((trk['customStartSec'] ?? '0').toString()) ?? 0;
    final TextEditingController secCtrl = TextEditingController(text: '$existing');

    final int? chosenSec = await showDialog<int>(
      context: context,
      builder: (ctx) {
        return AlertDialog(
          backgroundColor: const Color(0xFF0E172A),
          title: const Text(
            '⏱ Set Custom Start Second (Skip Intro)',
            style: TextStyle(fontSize: 14.5, fontWeight: FontWeight.w900, color: Color(0xFF00E5FF)),
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(trk['title'].toString(), style: const TextStyle(fontSize: 12, color: Colors.amberAccent)),
              const SizedBox(height: 10),
              Wrap(
                spacing: 6,
                runSpacing: 6,
                children: [0, 10, 15, 20, 30, 45].map((s) {
                  return ActionChip(
                    backgroundColor: const Color(0xFF172542),
                    label: Text(s == 0 ? '0s (Normal)' : 'Start @ ${s}s', style: const TextStyle(fontSize: 11)),
                    onPressed: () => Navigator.pop(ctx, s),
                  );
                }).toList(),
              ),
              const SizedBox(height: 10),
              TextField(
                controller: secCtrl,
                keyboardType: TextInputType.number,
                decoration: const InputDecoration(
                  labelText: 'Or enter exact second (e.g. 18)',
                ),
              ),
            ],
          ),
          actions: [
            TextButton(onPressed: () => Navigator.pop(ctx), child: const Text('Cancel')),
            ElevatedButton(
              style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFF00E676), foregroundColor: Colors.black),
              onPressed: () {
                final int v = int.tryParse(secCtrl.text.trim()) ?? 0;
                Navigator.pop(ctx, v.clamp(0, 300));
              },
              child: const Text('Save Cue', style: TextStyle(fontWeight: FontWeight.w900)),
            ),
          ],
        );
      },
    );

    if (chosenSec == null) return;
    trk['customStartSec'] = chosenSec;
    await VaultManager.setTrackCustomStartCue(id, chosenSec);
    if (mounted) {
      setState(() {});
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('⏱ Saved Start Cue @ ${chosenSec}s for ${trk['title']}')),
      );
    }
  }

  Future<void> _openLiveQueueAndBatchDownloadModal() async {
    _syncQueueWithVisibleIfChanged();
    showModalBottomSheet(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (ctx, setModalState) {
            return Container(
              height: MediaQuery.of(ctx).size.height * 0.78,
              padding: const EdgeInsets.all(10),
              child: GlassBox(
                padding: const EdgeInsets.all(14),
                borderRadius: 24,
                blur: 22,
                tintColor: const Color(0xFF0A1328),
                borderColor: const Color(0xFF00E5FF),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Row(
                      mainAxisAlignment: MainAxisAlignment.spaceBetween,
                      children: [
                        Expanded(
                          child: Text(
                            '📋 LIVE UP-NEXT QUEUE (${_playbackQueue.length} Songs)',
                            style: const TextStyle(fontSize: 13.5, fontWeight: FontWeight.w900, color: Color(0xFF00E5FF)),
                          ),
                        ),
                        ElevatedButton.icon(
                          style: ElevatedButton.styleFrom(
                            backgroundColor: const Color(0xFF00E676),
                            foregroundColor: Colors.black,
                            visualDensity: VisualDensity.compact,
                          ),
                          icon: const Icon(Icons.downloading_rounded, size: 15),
                          label: const Text('Batch Save Top 5', style: TextStyle(fontSize: 10, fontWeight: FontWeight.w900)),
                          onPressed: () async {
                            Navigator.pop(ctx);
                            final vis = _currentVisibleList().take(5).toList();
                            if (vis.isEmpty) return;
                            for (final trk in vis) {
                              await VaultManager.downloadTrack(trk, isEntry: false, category: _selectedOfflineCategory);
                            }
                            if (mounted) {
                              setState(() {});
                              ScaffoldMessenger.of(context).showSnackBar(
                                SnackBar(
                                  backgroundColor: Colors.green.shade800,
                                  content: Text('✅ Batch Saved Top ${vis.length} Songs to $_selectedOfflineCategory Offline Folder!'),
                                ),
                              );
                            }
                          },
                        ),
                      ],
                    ),
                    const SizedBox(height: 6),
                    Text(
                      _activeQueueScopeBanner,
                      style: const TextStyle(fontSize: 10.5, color: Colors.amberAccent, fontWeight: FontWeight.bold),
                    ),
                    const Divider(color: Colors.white24),
                    Expanded(
                      child: _playbackQueue.isEmpty
                          ? const Center(child: Text('Queue is empty — tap any song to start!', style: TextStyle(color: Colors.white60)))
                          : ListView.builder(
                              itemCount: _playbackQueue.length,
                              itemBuilder: (ctx, i) {
                                final item = _playbackQueue[i];
                                final bool isCur = (i == _queueIndex);
                                return ListTile(
                                  dense: true,
                                  leading: CircleAvatar(
                                    radius: 14,
                                    backgroundColor: isCur ? Colors.amberAccent : const Color(0xFF172542),
                                    child: Text(
                                      '#${i + 1}',
                                      style: TextStyle(
                                        fontSize: 10,
                                        fontWeight: FontWeight.w900,
                                        color: isCur ? Colors.black : Colors.white,
                                      ),
                                    ),
                                  ),
                                  title: Text(
                                    item['title'].toString(),
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: TextStyle(
                                      fontSize: 12.5,
                                      fontWeight: FontWeight.w900,
                                      color: isCur ? Colors.amberAccent : Colors.white,
                                    ),
                                  ),
                                  subtitle: Text(
                                    item['artist'].toString(),
                                    maxLines: 1,
                                    overflow: TextOverflow.ellipsis,
                                    style: const TextStyle(fontSize: 10.5, color: Colors.cyanAccent),
                                  ),
                                  trailing: Row(
                                    mainAxisSize: MainAxisSize.min,
                                    children: [
                                      if (!isCur && _playbackQueue.length > 1)
                                        IconButton(
                                          visualDensity: VisualDensity.compact,
                                          icon: const Icon(Icons.close_rounded, size: 17, color: Colors.white54),
                                          onPressed: () {
                                            setModalState(() {
                                              _playbackQueue.removeAt(i);
                                              if (i < _queueIndex) _queueIndex--;
                                            });
                                            setState(() {});
                                          },
                                        ),
                                      IconButton(
                                        visualDensity: VisualDensity.compact,
                                        icon: Icon(
                                          isCur ? Icons.volume_up_rounded : Icons.play_circle_fill_rounded,
                                          color: isCur ? const Color(0xFF00E676) : const Color(0xFF00E5FF),
                                        ),
                                        onPressed: () {
                                          Navigator.pop(ctx);
                                          _playFromQueueIndex(i);
                                        },
                                      ),
                                    ],
                                  ),
                                );
                              },
                            ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  void _openEqualizerAndSleepConsole() {
