                              final List<double> b = List<double>.from(p['bands'] as List);
                              setModalState(() {
                                _selectedEqPresetName = pName;
                                _customEqEnabled = isCust;
                                _bassBoostStrength = p['bass'] as double;
                                _loudnessGain = p['loud'] as double;
                                _eqBands = b;
