                  Text(
                    '⚡ Master Stage Loudness Enhancer: ${(_loudnessGain * 100).toInt()}%',
                    style: const TextStyle(fontSize: 11.5, color: Color(0xFF00E676), fontWeight: FontWeight.bold),
                  ),
