                                      child: TextField(
                                        controller: _searchCtrl,
                                        style: const TextStyle(fontSize: 13, color: Colors.white),
                                        decoration: InputDecoration(
                                          hintText: 'Search ANY song, movie, Marriage, Devotional, artist...',
